def fibonacci(n):
    """Returns the n-th Fibonacci number iteratively."""
    if n <= 0:
        return 0
    Fib_a, Fib_b = 0, 1
    if n == 1:
        return 1
    if n == 0:
        return 0
    if n == 1:
        return 1

    a, b = 0, 1
    for _ in range(2, n):
        a, b = b, a + b
    return b
